grok.supportRules:
_timestamp %{date("yyyy-MM-dd'T'HH:mm:ss.SSSSSSZ"):db.date}
_timestamp_mariadb_post_1015 (%{date("yyyy-MM-dd HH:mm:ss"):db.date}|%{date("yyyy-MM-dd  H:mm:ss"):db.date})
_rawtimestamp %{date("yyMMdd HH:mm:ss"):db.date}
_severity %{?>notSpace:db.severity}
_client_ip %{ipOrHost:network.client.ip}
_client_port %{integer:network.client.port}
_operation %{word:db.operation}
_database %{word:db.instance}
_raw_query %{data:db.statement}
_time_line \# Time: %{notSpace}(\s+%{notSpace})?
_user_line \# User@Host\: %{notSpace:db.user}\s+@\s+%{notSpace:db.host}\s+\[(%{notSpace:network.client.ip})?\](\s+Id\:\s+%{number:mysql.query.id})?
_instance_line use %{notSpace:db.instance};
_set_line SET timestamp=%{number:mysql.query.timestamp};
_query_line %{data:db.slow_statement}

# %p — process ID
_pg_pid %{integer:postgres.pid}
# %l — log line number within the session
_pg_line_num %{integer:postgres.line_num}
# %x — transaction ID
_pg_txid %{integer:postgres.txid}
# %c — session ID
_pg_session_id %{regex("[0-9a-f]+\\.[0-9a-f]+"):postgres.session_id}
# %v — virtual transaction ID
_pg_vxid (?:%{regex("[0-9]+/[0-9]+"):postgres.vxid})?
# %e — SQLSTATE
_pg_state_code %{regex("[A-Z0-9]{5}"):postgres.state_code:nullIf("00000")}
# %m / %t — log timestamp with / without milliseconds
# Accept standard timezone abbreviations (letters, digits, +, -) or an empty suffix.
_pg_timestamp %{regex("[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}(?:\\.[0-9]+)? (?:[0-9A-Za-z+-]+)?"):postgres.timestamp}
# %s — process start timestamp
_pg_session_start %{regex("[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}(?:\\.[0-9]+)? (?:[0-9A-Za-z+-]+)?"):postgres.session_start}
# %r — client host and optional port
_pg_remote (?:(?:%{ipOrHost:postgres.remote_host}\(%{integer:postgres.remote_port}\))|%{regex("\\[local\\]"):postgres.remote_host}|%{ipOrHost:postgres.remote_host})?
# %u — user name
_pg_user %{regex("\\S*"):postgres.user:nullIf("[unknown]")}
# %d — database name
_pg_dbname %{regex("\\S*"):postgres.dbname:nullIf("[unknown]")}
# %a — application name
_pg_app_name %{data:postgres.application_name:nullIf("[unknown]")}
# %h — client host only
_pg_remote_host %{regex("\\S*"):postgres.remote_host}
# %b — backend type
_pg_backend_type %{data:postgres.backend_type}
# %i — command tag
_pg_ps %{data:postgres.ps}
# Both body helpers parse the severity, optional SQLSTATE and message after the configured prefix.
# Consume the position suffix without publishing cursorpos or internalpos: text cannot distinguish them.
# Keep pgAudit's AUDIT: SESSION/OBJECT marker in the message instead of treating AUDIT as SQLSTATE.
_pg_body %{word:postgres.error_severity}:  (?:%{regex("(?!AUDIT: (?:SESSION|OBJECT),)[A-Z0-9]{5}"):postgres.state_code:nullIf("00000")}: )?%{data:postgres.message}(?: at character \d+)?
# When %e already captures SQLSTATE, consume its verbose-body copy without creating an array.
_pg_body_with_prefix_state %{word:postgres.error_severity}:  (?:%{regex("(?!AUDIT: (?:SESSION|OBJECT),)[A-Z0-9]{5}")}: )?%{data:postgres.message}(?: at character \d+)?

grok.matchRules:
# log_line_prefix = '%m [%p] %d %a %u %h %c '
pgprefix_dd_docs %{_pg_timestamp} \[%{_pg_pid}\] %{_pg_dbname} %{_pg_app_name} %{_pg_user} %{_pg_remote_host} %{_pg_session_id} %{_pg_body}

# log_line_prefix = '%m [%p] ' (PostgreSQL's built-in default)
default_format %{_pg_timestamp} \[%{_pg_pid}\] %{_pg_body}

# log_line_prefix = '%t-%c-' (Azure Database for PostgreSQL default)
pgprefix_azure %{_pg_timestamp}-%{_pg_session_id}-%{_pg_body}

# log_line_prefix = '<%t %r %a %d %u %p %c %i>'
pgprefix_bracket <%{_pg_timestamp} %{_pg_remote} %{_pg_app_name} %{_pg_dbname} %{_pg_user} %{_pg_pid} %{_pg_session_id} %{_pg_ps}>%{_pg_body}

# log_line_prefix = ' sql_error_code = %e time_ms = "%m" pid="%p" proc_start_time="%s" session_id="%c" vtid="%v" tid="%x" log_line="%l" %qdatabase="%d" connection_source="%r" user="%u" application_name="%a" ' (Heroku Postgres)
pgprefix_heroku \s*sql_error_code = %{_pg_state_code} time_ms = "%{_pg_timestamp}" pid="%{_pg_pid}" proc_start_time="%{_pg_session_start}" session_id="%{_pg_session_id}" vtid="%{_pg_vxid}" tid="%{_pg_txid}" log_line="%{_pg_line_num}" (?:database="%{_pg_dbname}" connection_source="%{_pg_remote}" user="%{_pg_user}" application_name="%{_pg_app_name}" )?%{_pg_body_with_prefix_state}

# log_line_prefix = 'pid=%p,user=%u,db=%d,app=%a,client=%h '
pgprefix_kv_client pid=%{_pg_pid},user=%{_pg_user},db=%{_pg_dbname},app=%{_pg_app_name},client=%{_pg_remote_host} %{_pg_body}

# log_line_prefix = '%t:%r:%u@%d:[%p]:' (Amazon RDS default)
pgprefix_rds %{_pg_timestamp}:%{_pg_remote}:%{_pg_user}@%{_pg_dbname}:\[%{_pg_pid}\]:%{_pg_body}

# log_line_prefix = '%m:%r:%u@%d:[%p]:%l:%e:%s:%v:%x:%c:%q%a:' (RDS with the enhanced-logging fields enabled)
pgprefix_rds_enhanced %{_pg_timestamp}:%{_pg_remote}:%{_pg_user}@%{_pg_dbname}:\[%{_pg_pid}\]:%{_pg_line_num}:%{_pg_state_code}:%{_pg_session_start}:%{_pg_vxid}:%{_pg_txid}:%{_pg_session_id}:(?:%{_pg_app_name}:)?%{_pg_body_with_prefix_state}

# log_line_prefix = '%m [%p][%b]: [%l-1] db=%d,user=%u '
pgprefix_verbose_user_backend %{_pg_timestamp} \[%{_pg_pid}\]\[%{_pg_backend_type}\]: \[%{_pg_line_num}-1\] db=%{_pg_dbname},user=%{_pg_user} %{_pg_body}

# log_line_prefix = '%m [%p]: [%l-1] db=%d,user=%u,host=%h '
pgprefix_verbose_user_host %{_pg_timestamp} \[%{_pg_pid}\]: \[%{_pg_line_num}-1\] db=%{_pg_dbname},user=%{_pg_user},host=%{_pg_remote_host} %{_pg_body}

# log_line_prefix = '%m [%p]: [%l-1] db=%d,user=%u '
pgprefix_verbose_user %{_pg_timestamp} \[%{_pg_pid}\]: \[%{_pg_line_num}-1\] db=%{_pg_dbname},user=%{_pg_user} %{_pg_body}

# This rule must precede pgprefix_atdb, which can mistake an @ inside a labeled field for user@database.
# log_line_prefix = '%m [%p] %q[user=%u,db=%d,app=%a] ' (pganalyze recommended prefix)
pgprefix_pganalyze %{_pg_timestamp} \[%{_pg_pid}\] (?:\[user=%{_pg_user},db=%{_pg_dbname},app=%{_pg_app_name}\] )?%{_pg_body}

# log_line_prefix = '%m [%p] %q%u@%d '
pgprefix_atdb %{_pg_timestamp} \[%{_pg_pid}\] (?:%{_pg_user}@%{_pg_dbname} )?%{_pg_body}

# log_line_prefix = '%t '
pgprefix_timestamp_only %{_pg_timestamp} %{_pg_body}

